  const fNetExpN = (data.p0Pa - pMinEx) * data.sM2; // ≈147 N
  const atmFN = data.p0Pa * data.sM2;
  const wAtmJ = data.p0Pa * data.sM2 * data.ampM; // 押し込むとき大気の仕事
