  const q2J = p2W * data.tS;
  const dT2K = q2J / (n * cpJ);
  const w2J = n * AH_R * dT2K;
  const du2J = n * cvJ * dT2K;
  const dV2M3 = (n * AH_R * dT2K) / p0;
  const dh2M = dV2M3 / S;
