    if (Math.abs(d.vCA - d.iEffA * d.xC) > 1e-9) return ['コンデンサの電圧が IXC と一致しません'];
    if (Math.abs(Math.sqrt(d.vRA * d.vRA + (d.vLA - d.vCA) * (d.vLA - d.vCA)) - scene.emfEffV) > 1e-9) return ['電圧のベクトル和が E と一致しません'];
