    if (Math.abs(d.pAfter - d.pBottom) > 1e-9) return ['衝突で運動量が保存していません'];
    if (Math.abs(d.keAfter - d.keBottom) > 1e-9) return ['衝突で運動エネルギーが保存していません'];
    if (Math.abs(d.fAfter - scene.f0Hz) > 1e-9) return ['衝突後の音が 440 Hz に戻っていません'];
