    if (Math.abs(d.sBlockM - (d.vBlockAfter * d.vBlockAfter) / (2 * d.aBlock)) > 1e-9) return ['ブロックのすべる距離が一致しません'];
    if (Math.abs(d.heatBlockJ - d.keBottom) > 1e-9) return ['ブロックの摩擦熱が一致しません'];
