    if (Math.abs(0.5 * k * s.xMax * s.xMax - m * g * s.xMax - f * s.xMax - s.keReturn) > 1e-9) return ['戻りのエネルギー収支が一致しません'];
    if (Math.abs(d.tTotal - (d.t1S + d.t2S + s.tComp + s.tRet + s.vReturn / g)) > 1e-9) return ['合計の時間が一致しません'];
