    if (Math.abs(d.procs[3].wJ - scene.p1Pa * (scene.v1M3 - scene.v2M3)) > 0.5) return ['等圧圧縮の仕事が pΔV と一致しません'];
    // 1サイクル：内部エネルギーの和は 0、仕事は吸収した熱−放出した熱、効率は W/Qin。
    const dUSum = d.procs.reduce((s, p) => s + p.dUJ, 0);
