    if (Math.abs(d.wNetJ - (d.qInJ - d.qOutJ)) > 0.5) return ['仕事が Qin − Qout と一致しません'];
    if (Math.abs(d.eta - d.wNetJ / d.qInJ) > 1e-9) return ['効率が W/Qin と一致しません'];
