      svg.appendChild(el('line', { x1: 288, y1: 152, x2: 312, y2: 152, stroke: '#333', 'stroke-width': 3 }));
      svg.appendChild(el('line', { x1: 300, y1: 152, x2: 300, y2: 210, stroke: '#333', 'stroke-width': 2 }));
