        svg.appendChild(el('circle', { cx: xOf(dMm), cy: yOf(0), r: 4, fill: '#b00', stroke: '#333', 'stroke-width': 1 }));
        const tL = el('text', { x: lx, y: ly, fill: '#b00' }); tL.textContent = label; svg.appendChild(tL);
