      svg.appendChild(el('line', { x1: 80, y1: 80, x2: 80, y2: 130, stroke: '#333', 'stroke-width': 2 }));
      svg.appendChild(el('line', { x1: 80, y1: 152, x2: 80, y2: 200, stroke: '#333', 'stroke-width': 2 }));
