      svg.appendChild(el('line', { x1: 290, y1: 106, x2: 338, y2: 106, stroke: '#888', 'stroke-width': 1.5, 'stroke-dasharray': '4 3' }));
      svg.appendChild(el('line', { x1: 290, y1: 70, x2: 338, y2: 106, stroke: '#333', 'stroke-width': 2 }));
