      const tC = el('text', { x: 318, y: 160 }); tC.textContent = 'C=100 μF'; svg.appendChild(tC);
      const tS = el('text', { x: 200, y: 238, 'text-anchor': 'middle' }); tS.textContent = 'スイッチ'; svg.appendChild(tS);
