      svg.appendChild(el('line', { x1: 60, y1: 220, x2: 340, y2: 220, stroke: '#333', 'stroke-width': 2 }));
      svg.appendChild(el('line', { x1: 60, y1: 60, x2: 60, y2: 220, stroke: '#333', 'stroke-width': 2 }));
