      svg.appendChild(el('circle', { cx: 210, cy: 140, r: 4, fill: 'blue', stroke: '#333', 'stroke-width': 1.5 }));
      svg.appendChild(el('line', { x1: 214, y1: 140, x2: 227, y2: 140, stroke: 'blue', 'stroke-width': 2, 'marker-end': 'url(#fig-arrow)' }));
